#pragma once#include <HcdStruct.h>struct CHcdSystemA{  enum  {    STATUS_UNKNOWN = 0,    STATUS_INIT    = 1,    STATUS_START   = 2,    STATUS_PAUSE   = 3,  };  BYTE StartStatus;// Состояние модели  __time64_t startTime;  double dModelT;// Модельное время (сек)  DWORD nStep;  __time64_t TimeB()// Время от начала модели (сек)  {    return (__time64_t)dModelT;  }  __time64_t TimeM()// Полное модельное время (сек)  {    return startTime + TimeB();  }};struct CHcdSystem : public CBase, public CHcdSystemA{  enum { TypeID = id_HCDSystem };  int Init();  int GetParams();  int SaveState();  int RestoreState( char * StrName );};